// Keep only connected accounts on the platforms chosen in the Configure node.
const cfg = $('Configure brand and topics').first().json;
const wanted = String(cfg.platformFilter || '').split(',').map(s => s.trim().toUpperCase()).filter(Boolean);
const accounts = $input.all().map(i => i.json);

const selected = accounts.filter(a => {
  const status = String(a.connectionStatus || 'CONNECTED').toUpperCase();
  const platform = String(a.platform || '').toUpperCase();
  return status === 'CONNECTED' && (wanted.length === 0 || wanted.includes(platform));
});

if (selected.length === 0) {
  throw new Error('No connected accounts matched the platform filter. Check the Configure node and your PostFast connections.');
}

return [{ json: {
  accountIds: selected.map(a => a.id ?? a.socialMediaId),
  accountList: selected.map(a => `${a.platform}: ${a.name ?? a.username ?? a.id}`).join(', ')
} }];

// Assign each post to next week's strongest slot, one item per post per account.
// Slots (UTC) from PostFast's analysis of 22,890 IG + 13,758 TikTok real posts:
// weekday 17:00-19:00 UTC band leads on reach; Saturday 14:00 UTC is the standout.
// Source: postfa.st/blog/best-time-to-post-on-instagram
const raw = $input.first().json;
let parsed = raw.message?.content ?? raw.output ?? raw;
if (typeof parsed === 'string') parsed = JSON.parse(parsed);
const posts = parsed.posts || [];
if (posts.length === 0) throw new Error('OpenAI returned no posts. Check the prompt output.');

const accountIds = $('Select target accounts').first().json.accountIds;

// [dayOfWeek(0=Sun..6=Sat), hourUTC]
const SLOTS = [[2, 17], [3, 18], [4, 19], [5, 19], [6, 14], [1, 17], [0, 17]];

function nextSlotDate(dow, hour, after) {
  const d = new Date(after);
  d.setUTCHours(hour, 0, 0, 0);
  while (d.getUTCDay() !== dow || d <= after) d.setUTCDate(d.getUTCDate() + 1);
  return d;
}

let cursor = new Date(Date.now() + 60 * 60 * 1000); // at least 1h ahead
const items = [];
posts.forEach((p, i) => {
  const [dow, hour] = SLOTS[i % SLOTS.length];
  const when = nextSlotDate(dow, hour, cursor);
  cursor = when;
  for (const accountId of accountIds) {
    items.push({ json: {
      socialMediaId: accountId,
      content: p.text,
      scheduledAt: when.toISOString()
    } });
  }
});

return items;
